var postorder = function(root) {
    const result = [];

    const dfs = (node) => {
        // Base case: null node
        if (!node) return;

        // Visit all children first (left-to-right)
        for (const child of node.children) {
            dfs(child);
        }

        // Then add the current node's value
        result.push(node.val);
    };

    dfs(root);
    return result;
};
